using UnityEngine;
using System.Collections.Generic;

public class CrateFinder
{
    public static string FindCrate()
    {
        var allObjects = Resources.FindObjectsOfTypeAll(typeof(GameObject)) as GameObject[];
        foreach (var obj in allObjects)
        {
            if (obj != null && obj.name.StartsWith("Crate #7"))
            {
                return obj.name;
            }
        }
        return "NOT_FOUND";
    }
}
